begin;
create function pg_temp.care_assert(ok boolean,label text) returns text language plpgsql as $$begin if ok is distinct from true then raise exception 'FAIL: %',label;end if;return label;end $$;
create function pg_temp.care_denied(stmt text,label text,expected text default '42501') returns text language plpgsql as $$begin begin execute stmt;exception when others then if sqlstate<>expected then raise exception 'Wrong error % for %',sqlstate,label;end if;return label;end;raise exception 'Unexpected success: %',label;end $$;
create temporary table inform_fixture(name text primary key,value jsonb);grant select,insert,update on inform_fixture to authenticated,service_role;
insert into inform_fixture values('period',jsonb_build_object('start',(date_trunc('week',now() at time zone 'America/Santiago')::date-7)::text));
create function pg_temp.ip()returns jsonb language sql as $$select jsonb_build_object('kind','weekly','start_day',value->>'start')from inform_fixture where name='period'$$;
create function pg_temp.ir()returns uuid language sql as $$select (value#>>'{}')::uuid from inform_fixture where name='report'$$;
insert into auth.users(id,email) select ('e1000000-0000-4000-8000-'||lpad(n::text,12,'0'))::uuid,'informs-sql-qa-'||n||'@example.test' from generate_series(1,8)n;
insert into public.admin_users(user_id,role,is_active)select ('e1000000-0000-4000-8000-'||lpad(n::text,12,'0'))::uuid,case when n=8 then 'editor'::public.admin_role else 'viewer'::public.admin_role end,true from generate_series(3,8)n;
insert into public.patient_profiles(id,auth_user_id,email,display_name)select ('e2000000-0000-4000-8000-'||lpad(n::text,12,'0'))::uuid,('e1000000-0000-4000-8000-'||lpad(n::text,12,'0'))::uuid,'informs-sql-qa-'||n||'@example.test','Persona informe QA '||n from generate_series(1,2)n;
insert into public.care_staff_capabilities(user_id,capabilities)select ('e1000000-0000-4000-8000-'||lpad(n::text,12,'0'))::uuid,array['care.directory.read','care.patient.read','care.records.read','care.records.create','care.family.read']||case when n in(6,7)then array['care.decisions.manage','care.reports.export']else array[]::text[]end from generate_series(3,7)n;
insert into public.care_assignments(patient_id,professional_id,specialty,starts_at,created_by)select 'e2000000-0000-4000-8000-000000000001',('e1000000-0000-4000-8000-'||lpad(n::text,12,'0'))::uuid,case n when 3 then 'psychology' when 4 then 'recovery' else 'direction'end,now()-interval '2 years','e1000000-0000-4000-8000-000000000006' from generate_series(3,7)n;
insert into public.care_assignments(patient_id,professional_id,specialty,starts_at,created_by)values('e2000000-0000-4000-8000-000000000002','e1000000-0000-4000-8000-000000000006','direction',now()-interval '2 years','e1000000-0000-4000-8000-000000000006');
insert into public.care_events(id,title,kind,starts_at,ends_at,professional_id,modality,status,closed_at,created_by)select ('e3000000-0000-4000-8000-'||lpad(n::text,12,'0'))::uuid,'Sesión informe neutral '||n,case n when 1 then 'individual' when 2 then 'recovery' when 3 then 'family' else 'sport'end,
 ((pg_temp.ip()->>'start_day')::date+1)::timestamp at time zone 'America/Santiago'+interval '10 hours',((pg_temp.ip()->>'start_day')::date+1)::timestamp at time zone 'America/Santiago'+interval '11 hours',
 ('e1000000-0000-4000-8000-'||lpad((case n when 1 then 3 else 4 end)::text,12,'0'))::uuid,'in_person',case when n=4 then 'cancelled'else 'completed'end,now()-interval '1 hour','e1000000-0000-4000-8000-000000000006' from generate_series(1,4)n;
insert into public.care_event_participants(event_id,patient_id,attendance)select id,'e2000000-0000-4000-8000-000000000001',case when kind='individual'then 'present'else 'absent'end from public.care_events where id::text like 'e3000000-%';
insert into public.care_session_records(id,patient_id,event_id,author_id,specialty,occurred_at,status,revision,first_finalized_at)select 'e4000000-0000-4000-8000-000000000001','e2000000-0000-4000-8000-000000000001',id,professional_id,'psychology',starts_at,'final',1,now() from public.care_events where id='e3000000-0000-4000-8000-000000000001';
insert into private.care_record_versions(id,record_id,revision,occurred_at,payload,reason,actor_id)select 'e5000000-0000-4000-8000-000000000001',id,1,occurred_at,'{"objective":"Objetivo autorizado QA","evolution":"stable","facts":"Hechos registrados QA","difficulties":"Dificultad registrada QA"}','Original QA',author_id from public.care_session_records where id='e4000000-0000-4000-8000-000000000001';
insert into private.care_record_reserves values('e5000000-0000-4000-8000-000000000001','RESERVA EXCLUIDA INFORME QA');
insert into public.care_report_rules(id,kind,effective_on,opens_local,closes_local,close_next_day,basis,weekdays,fields,required_fields,approved_by,reason)values('e6000000-0000-4000-8000-000000000001','morning','2020-01-01','08:00','11:00',false,'active_days',array[1,2,3,4,5,6,7],array['state'],array['state'],'e1000000-0000-4000-8000-000000000006','Regla QA neutral');
insert into public.care_report_obligations(id,patient_id,local_day,kind,rule_id,opens_at,closes_at,fields,required_fields,required,requirement_reason,generated_at)select ('e7000000-0000-4000-8000-'||lpad(n::text,12,'0'))::uuid,'e2000000-0000-4000-8000-000000000001',(pg_temp.ip()->>'start_day')::date+n,'morning','e6000000-0000-4000-8000-000000000001',((pg_temp.ip()->>'start_day')::date+n)::timestamp at time zone 'America/Santiago'+interval '8 hours',((pg_temp.ip()->>'start_day')::date+n)::timestamp at time zone 'America/Santiago'+interval '11 hours',array['state'],array['state'],true,'Obligación QA',((pg_temp.ip()->>'start_day')::date+n)::timestamp at time zone 'America/Santiago'+interval '8 hours' from generate_series(1,2)n;
insert into public.care_daily_reports(id,patient_id,author_id,answers,first_submitted_at)select id,patient_id,'e1000000-0000-4000-8000-000000000001','{"state":"Estado referido QA"}',closes_at from public.care_report_obligations where id='e7000000-0000-4000-8000-000000000001';

update public.care_staff_capabilities set capabilities=capabilities||array['care.reports.export']where user_id='e1000000-0000-4000-8000-000000000004';
create function pg_temp.rc_month()returns date language sql as $$select (date_trunc('month',now()at time zone 'America/Santiago')-interval '1 month')::date$$;
create function pg_temp.rc_week()returns date language sql as $$select pg_temp.rc_month()+((8-extract(isodow from pg_temp.rc_month())::integer)%7)$$;
create function pg_temp.rr()returns uuid language sql as $$select (value#>>'{}')::uuid from inform_fixture where name='recovery_report'$$;
create function pg_temp.month_text(content text)returns jsonb language sql security definer set search_path='' as $$select jsonb_build_object('advances',content,'coverage',content,'difficulties',content,'support',content,'next_goals',content,'changes',(select jsonb_object_agg(d->>'key',content)from public.care_recovery_rubrics r cross join lateral jsonb_array_elements(r.dimensions)d where r.id='c0000000-0000-4000-8000-000000000001'))$$;
create function pg_temp.month_action(rev integer,content text)returns jsonb language sql as $$select jsonb_build_object('id',pg_temp.rr(),'version',rev,'reason','Acción neutral mensual QA','recovery_text',pg_temp.month_text(content),'confirm',true,'recipient_id','e1000000-0000-4000-8000-000000000006')$$;
set local role authenticated;select set_config('request.jwt.claim.sub','e1000000-0000-4000-8000-000000000004',true);
select public.care_rc_week_write('finalize',jsonb_build_object('id','e4000000-0000-4000-8000-000000000080','patient_id','e2000000-0000-4000-8000-000000000001','rubric_id','c0000000-0000-4000-8000-000000000001','week_start',pg_temp.rc_week(),'version',0,'reason','SE histórica neutral QA','confirm',true,'occurred_at',pg_temp.rc_week()::timestamp at time zone 'America/Santiago','evaluated_at',now(),'payload',jsonb_build_object('dimensions',(select jsonb_agg(jsonb_build_object('key',d->>'key','status','SE','level',null,'evidence_sufficient',false,'evidence','','support','','result','','difficulties','','se_reason','Sin evidencia suficiente neutral QA','record_ids','[]'::jsonb,'commitment_ids','[]'::jsonb,'next_commitment_id',null))from jsonb_array_elements(public.care_rc_catalog()->0->'dimensions')d))));
insert into inform_fixture values('recovery_report',to_jsonb(public.care_inform_write('generate',jsonb_build_object('kind','monthly','start_day',pg_temp.rc_month(),'patient_id','e2000000-0000-4000-8000-000000000001'))));
select pg_temp.care_assert(public.care_rc_monthly_context(pg_temp.rr())->>'can_write'='true','Actual Recovery author can edit own monthly version');
select pg_temp.care_assert((select count(*)=1 from jsonb_array_elements(public.care_inform_read(pg_temp.rr(),null,1,true)->'snapshot'->'sources')s where s->>'metric'='recovery_weekly' and s->>'source_id'='e4000000-0000-4000-8000-000000000080' and s->>'revision'='1'),'Existing deterministic report snapshot includes real weekly reference and revision');
select pg_temp.care_assert((select s->>'body' like '%SE — Sin evaluar%' and s->>'body' like '%Planificación personal%' from jsonb_array_elements(public.care_inform_read(pg_temp.rr(),null,1,true)->'snapshot'->'sources')s where s->>'metric'='recovery_weekly'),'Weekly source preserves exact labels and explicit SE, no inferred conclusion');
select pg_temp.care_denied($$select public.care_inform_write('recovery_draft',pg_temp.month_action(1,'Neutral')||jsonb_build_object('recovery_text','{}'::jsonb))$$,'RPC rejects missing monthly keys, not only client validation','P0001');
select public.care_inform_write('recovery_draft',pg_temp.month_action(1,''));
select pg_temp.care_assert(public.care_inform_read(pg_temp.rr())->'version'->>'recovery_delivered_at' is null,'Incomplete professional draft is not delivery');
select pg_temp.care_denied($$select public.care_inform_write('recovery_deliver',pg_temp.month_action(2,''))$$,'Delivery rejects incomplete monthly text','P0001');
select public.care_inform_write('recovery_draft',pg_temp.month_action(2,'Constancia neutral de información insuficiente QA'));
select pg_temp.care_denied($$select public.care_inform_write('recovery_deliver',pg_temp.month_action(3,'')||jsonb_build_object('recipient_id','e1000000-0000-4000-8000-000000000004'))$$,'Recovery is not forged Direction recipient');
select public.care_inform_write('recovery_deliver',pg_temp.month_action(3,''));
select pg_temp.care_assert(public.care_inform_read(pg_temp.rr())->'version'->>'recovery_delivered_by'='e1000000-0000-4000-8000-000000000004' and public.care_inform_read(pg_temp.rr())->'version'->>'recovery_reviewed_at' is null,'Delivery records real author and remains distinct from Direction review');
select pg_temp.care_denied($$select public.care_inform_write('recovery_deliver',pg_temp.month_action(3,''))$$,'Stale retry cannot duplicate delivery','40001');
select pg_temp.care_denied($$select public.care_inform_write('recovery_review',pg_temp.month_action(4,''))$$,'Recovery cannot sign review as Direction');
select public.care_inform_write('review',pg_temp.month_action(4,'')||jsonb_build_object('confirm_review',true));
select pg_temp.care_assert(public.care_inform_read(pg_temp.rr())->'version'->'recovery_text' is not null and public.care_inform_read(pg_temp.rr())->'version'->>'recovery_delivered_at' is not null and public.care_inform_read(pg_temp.rr())->'version'->>'recovery_reviewed_at' is null,'Existing general review preserves Recovery text and delivery, without forging Direction review');
select pg_temp.care_denied($$select private.care_inform_previous_write('generate','{}')$$,'Renamed previous report writer has no direct authenticated grant');
select set_config('request.jwt.claim.sub','e1000000-0000-4000-8000-000000000006',true);
select pg_temp.care_assert((select x->>'recovery_assigned_review'='true' from jsonb_array_elements(public.care_inform_list()->'rows')x where x->>'id'=pg_temp.rr()::text),'Pending review assigned to Direction is actionable in existing report list');
select pg_temp.care_denied($$select public.care_inform_write('recovery_draft',pg_temp.month_action(5,'Suplantada'))$$,'Direction does not silently overwrite original professional monthly text');
select public.care_inform_write('recovery_review',pg_temp.month_action(5,''));
select pg_temp.care_assert(public.care_inform_read(pg_temp.rr())->'version'->>'recovery_reviewed_by'='e1000000-0000-4000-8000-000000000006','Direction review records actual authenticated reviewer');
select pg_temp.care_assert(public.care_inform_read(pg_temp.rr(),4)->'version'->>'recovery_reviewed_at' is null and jsonb_array_length(public.care_inform_read(pg_temp.rr())->'history')=6,'Original delivery and every prior version conserved');
select pg_temp.care_assert(public.care_rc_monthly_context(public.care_inform_write('generate',jsonb_build_object('kind','monthly','start_day',pg_temp.rc_month(),'patient_id','e2000000-0000-4000-8000-000000000002')))->>'eligible'='false','Monthly without Recovery assignment, sources or text does not impose Recovery delivery on other specialties');
select set_config('request.jwt.claim.sub','e1000000-0000-4000-8000-000000000001',true);select pg_temp.care_denied($$select public.care_rc_monthly_context(pg_temp.rr())$$,'Patient cannot read Recovery report context');
select set_config('request.jwt.claim.sub','e1000000-0000-4000-8000-000000000008',true);select pg_temp.care_denied($$select public.care_rc_monthly_context(pg_temp.rr())$$,'CMS without clinical export capabilities cannot read monthly context');
reset role;update public.care_assignments set ends_at=now() where professional_id='e1000000-0000-4000-8000-000000000004';
set local role authenticated;select set_config('request.jwt.claim.sub','e1000000-0000-4000-8000-000000000006',true);
select pg_temp.care_assert(public.care_rc_monthly_context(pg_temp.rr())->>'eligible'='true','Historical Recovery monthly text remains visible to authorized Direction after original assignment ends');
select set_config('request.jwt.claim.sub','e1000000-0000-4000-8000-000000000004',true);
select pg_temp.care_denied($$select public.care_inform_read(pg_temp.rr())$$,'Revoked original author cannot read saved monthly report');
select pg_temp.care_denied($$select public.care_inform_pdf_begin(pg_temp.rr(),6)$$,'Revocation blocks monthly export too');
rollback;
